export function evaluateRequestQuota(timestamps, now, limit, windowMs) {
  if (!Number.isSafeInteger(now) || !Number.isSafeInteger(limit) || limit <= 0 || !Number.isSafeInteger(windowMs) || windowMs <= 0) throw new Error('Invalid quota');
  const recent = [];
  for (const stamp of timestamps) {
    if (!Number.isSafeInteger(stamp) || stamp > now) throw new Error('Invalid timestamp');
    if (stamp > now - windowMs) recent.push(stamp);
  }
  if (recent.length < limit) return { allowed: true, remaining: limit - recent.length - 1, retryAfterMs: 0 };
  recent.sort((a,b) => a-b);
  const releaseTime = recent[recent.length - limit] + windowMs;
  return { allowed: false, remaining: 0, retryAfterMs: releaseTime - now };
}
